import { patchHtml } from './dom-patch.mjs';
import { phoneIcon } from './icons.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photoLibraryEntries(rows){return [...new Map((rows??[]).filter(x=>x&&/^(?:https?:|blob:|\/|data:image\/(?:png|jpeg|webp|gif);)/.test(String(x.src))).map(x=>[x.id??x.src,{...x,id:x.id??x.src}])).values()];}
export function mountIosPhotos(container,{getLibrary,importFiles,deletePhoto,onHome,notify,cache=new Map()}){
 const doc=container.ownerDocument,win=doc.defaultView;let photos=[],tab='library',filter='all',search='',album='',viewer='',viewerIds=[],zoom=false,destroyed=false,epoch=0,loading=true;
 const favourites=cache.get('favourites')??new Set();cache.set('favourites',favourites);
 const selected=()=>photos.find(x=>x.id===viewer),visible=()=>photos.filter(x=>(!album||album==='favourites'?album!=='favourites'||favourites.has(x.id):x.albumId===album)&&(filter==='all'||x.type===filter)&&(tab!=='search'||!search||[x.name,x.label].join(' ').includes(search)));
 const viewerPhotos=()=>viewerIds.map(id=>photos.find(x=>x.id===id)).filter(Boolean);
 const tile=photo=>`<button class="ios-photo-tile" data-photo="${esc(photo.id)}" aria-label="查看${esc(photo.name)}${esc(photo.label??'照片')}"><img src="${esc(photo.src)}" alt="${esc(photo.name)}" loading="lazy" draggable="false">${favourites.has(photo.id)?'<span>♥</span>':''}</button>`;
 function render(){if(destroyed)return;const item=selected(),screen=container.closest('.ip-screen');if(screen)screen.dataset.theme=item?'photos-dark':'photos';let body;
 if(item){const viewing=viewerPhotos(),index=viewing.indexOf(item);body=`<section class="ios-photo-viewer"><header><button data-photo-back aria-label="返回相册">${phoneIcon('back')}</button><span><strong>${esc(item.name)}</strong><small>${esc(item.label??'照片')}</small></span><button data-photo-zoom aria-label="${zoom?'还原照片':'放大照片'}">${phoneIcon('search')}</button></header><div class="ios-photo-canvas ${zoom?'is-zoomed':''}"><img src="${esc(item.src)}" alt="${esc(item.name)}${esc(item.label??'照片')}"></div><footer><button data-photo-step="-1" aria-label="上一张照片" ${index<=0?'disabled':''}>${phoneIcon('back')}</button><button class="ios-photo-heart" data-photo-favourite aria-label="${favourites.has(item.id)?'取消收藏照片':'收藏照片'}" aria-pressed="${favourites.has(item.id)}">${favourites.has(item.id)?'♥':'♡'}</button><span>${index+1} / ${viewing.length}</span><button data-photo-delete aria-label="删除这张照片">删除</button><button data-photo-step="1" aria-label="下一张照片" ${index>=viewing.length-1?'disabled':''}>${phoneIcon('chevron')}</button></footer></section>`;}
 else{const albums=[...new Map(photos.map(x=>[x.albumId,{name:x.name,id:x.albumId}])).values()];body=`<section class="ios-photos"><header class="ios-photos-nav"><button data-photo-import>＋ 导入照片</button><input type="file" data-photo-file accept="image/*" multiple hidden><span>${loading?'正在读取照片…':photos.length+' 张照片'}</span></header><div class="ios-photos-scroll"><h1>${album==='favourites'?'个人收藏':album?esc(albums.find(x=>x.id===album)?.name??'相簿'):tab==='albums'?'相簿':tab==='search'?'搜索':'照片'}</h1>${album?'<button class="ios-album-back" data-album-back>‹ 所有相簿</button>':''}${tab==='search'?`<label class="ios-photo-search">${phoneIcon('search')}<input data-photo-search aria-label="搜索照片" placeholder="搜索照片文件名" value="${esc(search)}"></label>`:''}${tab==='library'&&!album?`<div class="ios-photo-filters">${[['all','所有照片'],['imported','我的照片']].map(([id,label])=>`<button data-photo-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>`:''}${tab==='albums'&&!album?`<div class="ios-albums"><button data-album="favourites" aria-label="打开个人收藏"><span class="ios-favourite-cover">♡</span><strong>个人收藏</strong><small>${photos.filter(x=>favourites.has(x.id)).length}</small></button>${albums.map(a=>{const list=photos.filter(x=>x.albumId===a.id);return `<button data-album="${esc(a.id)}" aria-label="打开${esc(a.name)}相簿"><img src="${esc(list[0].src)}" alt="${esc(a.name)}"><strong>${esc(a.name)}</strong><small>${list.length} 张照片</small></button>`;}).join('')}</div>`:`<div class="ios-photo-grid">${visible().map(tile).join('')}</div>${visible().length?'':`<p class="ios-photo-empty">${loading?'正在读取照片…':'暂无照片'}</p>`}<p class="ios-photo-count">${visible().length} 张照片</p>`}</div><nav class="ios-photos-tabs" aria-label="相册导航">${[['library','图库','photos'],['albums','相簿','inventory'],['search','搜索','search']].map(([id,label,icon])=>`<button data-photo-tab="${id}" aria-pressed="${tab===id}">${phoneIcon(icon)}${label}</button>`).join('')}</nav></section>`;}
 patchHtml(container,body);
 }
 async function refresh(){const token=++epoch;try{const next=photoLibraryEntries(await getLibrary());if(destroyed||token!==epoch)return;if(!loading&&JSON.stringify(next)===JSON.stringify(photos)&&container.firstChild)return;loading=false;photos=next;if(!selected())viewer='';render();}catch(error){loading=false;render();notify(error.message);}}
 function click(event){const button=event.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;if('photoImport'in d){container.querySelector('[data-photo-file]').click();return;}if('photoDelete'in d){void deletePhoto?.(viewer).then(()=>{viewer='';return refresh();}).catch(e=>notify(e.message));return;}if('photoHome'in d){onHome();return;}if(d.photo){viewerIds=visible().map(x=>x.id);viewer=d.photo;zoom=false;render();return;}if('photoBack'in d){viewer='';zoom=false;render();return;}if(d.photoTab){if(d.photoTab===tab&&!album)return;tab=d.photoTab;album='';filter='all';render();return;}if(d.photoFilter){filter=d.photoFilter;render();return;}if(d.album){album=d.album;filter='all';render();return;}if('albumBack'in d){album='';render();return;}if(d.photoStep){const viewing=viewerPhotos(),index=viewing.indexOf(selected())+Number(d.photoStep);viewer=viewing[index]?.id??viewer;zoom=false;render();return;}if('photoFavourite'in d){if(favourites.has(viewer))favourites.delete(viewer);else favourites.add(viewer);render();return;}if('photoZoom'in d){zoom=!zoom;render();}}
 async function change(event){if(event.target.hasAttribute('data-photo-file'))try{await importFiles?.([...event.target.files]);await refresh();notify('照片已保存在此浏览器');}catch(e){notify(e.message);}}
 function input(event){if(event.target.hasAttribute('data-photo-search')){search=event.target.value;render();}}
 function key(event){if(event.key==='Escape'&&viewer){viewer='';render();}if(viewer&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const viewing=viewerPhotos(),index=viewing.indexOf(selected())+(event.key==='ArrowRight'?1:-1);viewer=viewing[index]?.id??viewer;zoom=false;render();}}
 container.addEventListener('change',change);container.addEventListener('click',click);container.addEventListener('input',input);container.addEventListener('keydown',key);render();void refresh();return{refresh,destroy(){destroyed=true;epoch++;container.removeEventListener('change',change);container.removeEventListener('click',click);container.removeEventListener('input',input);container.removeEventListener('keydown',key);}};
}
